-- Repeatable demo seed. Stable business keys are preserved; UUIDs are generated by PostgreSQL.
insert into public.organizations (key, name, type) values
('tpa-demo','Compatibility TPA for demo','tpa'), ('tpa-waepa','Compatibility TPA for waepa','tpa'),
('tpa-asce','Pearl Insurance','tpa'), ('tpa-ama','Compatibility TPA for ama','tpa')
on conflict (key) do update set name = excluded.name, updated_at = now();

insert into public.clients (organization_id, key, name, acronym)
select o.id, v.key, v.name, v.acronym from (values
('tpa-demo','demo','Portal Demo','DEMO'), ('tpa-waepa','waepa','Worldwide Assurance for Employees of Public Agencies','WAEPA'),
('tpa-asce','asce','American Society of Civil Engineers','ASCE'), ('tpa-ama','ama','American Medical Association','AMA')) v(org_key,key,name,acronym)
join public.organizations o on o.key = v.org_key
on conflict (key) do update set name = excluded.name, acronym = excluded.acronym, updated_at = now();

insert into public.sites (client_id, key, name, display_name, environment, template_type, legacy_client_id)
select c.id, v.key, v.name, v.name, 'demo', v.template_type, v.legacy_client_id from (values
('demo','demo-default','Default Site','multi','demo'), ('waepa','waepa-standard','Standard Site','multi','waepa'),
('waepa','waepa-gi','Guaranteed Issue Site','single','waepagi'), ('asce','asce-default','Default Site','multi','asce'),
('ama','ama-default','Default Site','multi','ama')) v(client_key,key,name,template_type,legacy_client_id)
join public.clients c on c.key = v.client_key
on conflict (key) do update set name = excluded.name, display_name = excluded.display_name, updated_at = now();

insert into public.site_coverages (site_id, coverage_key)
select s.id, v.coverage_key from (values ('waepa-standard','li-group-term'),('waepa-standard','di-short-term')) v(site_key,coverage_key)
join public.sites s on s.key=v.site_key on conflict (site_id,coverage_key) do update set enabled=true,updated_at=now();
insert into public.site_products (site_id, product_key)
select s.id, v.product_key from (values ('waepa-standard','li-group-term'),('waepa-standard','di-short-term')) v(site_key,product_key)
join public.sites s on s.key=v.site_key on conflict (site_id,product_key) do update set enabled=true,updated_at=now();
insert into public.site_riders (site_id, rider_key)
select s.id, v.rider_key from (values ('waepa-standard','cir'),('waepa-standard','abi')) v(site_key,rider_key)
join public.sites s on s.key=v.site_key on conflict (site_id,rider_key) do update set enabled=true,updated_at=now();
insert into public.site_configurations (site_id,configuration_key,value_json,source,effective_date)
select s.id,'setCoverageAmount','250000'::jsonb,'legacy_seed','2026-09-01'::date from public.sites s where s.key='waepa-standard'
on conflict (site_id,configuration_key,effective_date) do update set value_json=excluded.value_json,updated_at=now();

insert into public.releases (release_key,name,release_date,status,notes) values
('REL-2026-10','October 2026 Portal Release','2026-10-15','QA','Current template, email, accessibility, and client presentation changes.'),
('REL-2026-11','November 2026 Portal Release','2026-11-19','Planning','Planned TPA verification and rule documentation scope.')
on conflict (release_key) do update set name=excluded.name, release_date=excluded.release_date, status=excluded.status, notes=excluded.notes, updated_at=now();

insert into public.change_requests (change_number,title,description,status,requested_by,target_release_id)
select v.change_number,v.title,v.title,v.status,v.requested_by,r.id from (values
('CHG-1042','WAEPA product and coverage copy updates','QA','QA','REL-2026-10'),
('CHG-1041','Standardize advisor email templates','Development','Marketing','REL-2026-10'),
('CHG-1039','TPA verification flow documentation','Review','Portal Admin','REL-2026-11')) v(change_number,title,status,requested_by,release_key)
join public.releases r on r.release_key=v.release_key
on conflict (change_number) do update set title=excluded.title,status=excluded.status,target_release_id=excluded.target_release_id,updated_at=now();

insert into public.applications (application_number,site_id,product_key,status,current_action_owner_type,submitted_at)
select v.application_number,s.id,v.product_key,v.status::public.application_status,v.owner::public.action_owner_type,v.submitted_at::timestamptz from (values
('APP-78214','waepa-standard','Group Term Life','Pending TPA Review','TPA','2026-09-22T12:00:00Z'),
('APP-78198','asce-default','Term Life','Underwriting','NYL','2026-09-21T12:00:00Z'),
('APP-78155','waepa-gi','Guaranteed Issue Life','In Progress','Applicant',null)) v(application_number,site_key,product_key,status,owner,submitted_at)
join public.sites s on s.key=v.site_key
on conflict (application_number) do update set status=excluded.status,current_action_owner_type=excluded.current_action_owner_type,updated_at=now();

insert into public.analytics_metrics (metric_key,name,description,unit,source) values
